//! Golden SDK vectors generated by Rust/Anchor, independent of the TS encoder.
use anchor_lang::{prelude::Pubkey, InstructionData, ToAccountMetas};

fn main() {
    let owner = Pubkey::new_from_array([7; 32]);
    let agent = Pubkey::new_from_array([8; 32]);
    let recipient = Pubkey::new_from_array([9; 32]);
    let program = solana_guard::id();
    let pda = |seeds: &[&[u8]]| Pubkey::find_program_address(seeds, &program).0;
    let config = pda(&[solana_guard::AGENT_SEED, owner.as_ref(), agent.as_ref()]);
    let policy = pda(&[solana_guard::POLICY_SEED, config.as_ref()]);
    let nonce = pda(&[solana_guard::NONCE_SEED, owner.as_ref(), agent.as_ref()]);
    let vault = pda(&[solana_guard::VAULT_SEED, config.as_ref()]);
    let log = pda(&[
        solana_guard::TX_LOG_SEED,
        config.as_ref(),
        &513u64.to_le_bytes(),
    ]);
    let system_program = anchor_lang::system_program::ID;
    let manage = || {
        solana_guard::accounts::ManageVault {
            owner,
            agent_config: config,
            vault,
            system_program,
        }
        .to_account_metas(None)
    };
    let vectors = [
        (
            "register",
            solana_guard::instruction::RegisterAgent {}.data(),
            solana_guard::accounts::RegisterAgent {
                owner,
                agent,
                agent_config: config,
                agent_nonce: nonce,
                system_program,
            }
            .to_account_metas(None),
        ),
        (
            "set",
            solana_guard::instruction::SetPolicy {
                max_spend_per_tx: 9_007_199_254_740_993,
                daily_limit: 9_007_199_254_741_993,
                allowed_protocols: vec![system_program, recipient],
            }
            .data(),
            solana_guard::accounts::SetPolicy {
                owner,
                agent_config: config,
                policy,
                system_program,
            }
            .to_account_metas(None),
        ),
        (
            "update",
            solana_guard::instruction::UpdatePolicy {
                max_spend_per_tx: None,
                daily_limit: Some(0),
                allowed_protocols: Some(vec![]),
                is_active: Some(false),
            }
            .data(),
            solana_guard::accounts::UpdatePolicy {
                owner,
                agent_config: config,
                policy,
            }
            .to_account_metas(None),
        ),
        (
            "pause",
            solana_guard::instruction::ToggleAgent { is_active: false }.data(),
            solana_guard::accounts::ToggleAgent {
                owner,
                agent_config: config,
            }
            .to_account_metas(None),
        ),
        (
            "deposit",
            solana_guard::instruction::DepositSol { amount: 101 }.data(),
            manage(),
        ),
        (
            "withdraw",
            solana_guard::instruction::WithdrawSol { amount: 101 }.data(),
            manage(),
        ),
        (
            "transfer",
            solana_guard::instruction::ValidateAndExecute {
                amount: 101,
                target_protocol: system_program,
            }
            .data(),
            solana_guard::accounts::ValidateAndExecute {
                agent,
                owner,
                agent_config: config,
                policy,
                agent_nonce: nonce,
                tx_log: log,
                vault,
                recipient,
                system_program,
            }
            .to_account_metas(None),
        ),
    ];
    println!("{{\"owner\":\"{owner}\",\"agent\":\"{agent}\",\"recipient\":\"{recipient}\",\"config\":\"{config}\",\"policy\":\"{policy}\",\"nonce\":\"{nonce}\",\"vault\":\"{vault}\",\"log\":\"{log}\",\"vectors\":[");
    for (i, (name, data, accounts)) in vectors.iter().enumerate() {
        let hex: String = data.iter().map(|byte| format!("{byte:02x}")).collect();
        let accounts: Vec<String> = accounts
            .iter()
            .map(|a| {
                format!(
                    "{{\"pubkey\":\"{}\",\"isSigner\":{},\"isWritable\":{}}}",
                    a.pubkey, a.is_signer, a.is_writable
                )
            })
            .collect();
        println!(
            "{}{{\"name\":\"{name}\",\"data\":\"{hex}\",\"keys\":[{}]}}",
            if i == 0 { "" } else { "," },
            accounts.join(",")
        );
    }
    println!("]}}");
}
